func TestMongoOCCBulkModels_ShadowWithoutUpdatedAtAndPruneLeakedSourceFieldValues_LiveMongo(t *testing.T) {
	cfgFile, _ := filepath.Abs("../../../config/config-local.yml")
	if _, statErr := os.Stat(cfgFile); statErr != nil {
		t.Fatalf("config-local.yml not found at %s: %v", cfgFile, statErr)
	}
	t.Setenv("CFG_PATH", cfgFile)

	cfg, err := config.NewConfig()
	if err != nil {
		t.Fatalf("cannot load config: %v", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	connMgr := source.NewConnectionManager(cfg, zap.NewNop())
	defer connMgr.Registry().Close()

	sysDB, err := connMgr.GetSystemDB(ctx)
	if err != nil || sysDB == nil {
		t.Fatalf("system DB unavailable: %v", err)
	}

	var mongoConnCode string
	_ = sysDB.WithContext(ctx).Raw(`
		SELECT connection_code FROM cdc_system.connection_registry
		 WHERE lower(engine_type) = 'mongodb' AND role_type = 'master' AND status = 'active' LIMIT 1
	`).Scan(&mongoConnCode).Error
	if mongoConnCode == "" {
		t.Fatal("expected active MongoDB master connection (role_type='master') in connection_registry")
	}

	client, err := connMgr.GetMasterMongoClient(ctx, mongoConnCode)
	if err != nil || client == nil {
		t.Fatalf("cannot connect to live MongoDB (%s): %v", mongoConnCode, err)
	}

